def card(a,b,c,d):
    t=[('cyan','How it works'),('emerald','What we use'),('rose','Rules we keep'),('amber','When something fails')]
    return [dict(dot=k,title=n,items=i) for (k,n),i in zip(t,(a,b,c,d))]
